mkdir qa && cat > qa/test_contacts.py <<'EOF'
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def student(last, first, section, email):
    return Student("1", last, first, section, email)


class ContactRowsTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = contact_rows([
            student("Young", "Al", "B", "al@x.org"),
            student("Adams", "Bea", "A", "bea@x.org"),
        ])
        self.assertEqual(rows, [
            "Adams, Bea  A  bea@x.org",
            "Young, Al   B  al@x.org",
        ])

    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(ProjectError, "Young, Al"):
            contact_rows([student("Young", "Al", "B", None)])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
